startGuideActionCreate: "Criar algum(a/ns/as)",
startGuideActionMenu: "Selecione o menu",
startGuideActivity: "Atividades são as tarefas planejadas para o seu projeto. <br/>Você pode criar a estrutura analítica do seu projeto (WBS). <br/>Não há limite para níveis nesta estrutura em fases / sub-fases / atividades / sub-atividades...",
startGuideAffectation: "Um recurso deve estar atribuído ao projeto para ver os itens deste projeto.<br/>A atribuição a um projeto automaticamente dá visibilidade também aos itens dos sub-projetos.",
startGuideClient: "Clientes são as entidades para as quais você está trabalhando.<br/>Pode ser interno ou externo à sua organização.",
startGuideContact: "Contatos são as pessoas com quem você mantém contato / relacionamento nos seus clientes.",
startGuideFooter: "Estas são as principais funcionalidades. <br/>Após estar familiarizado com estas funcionalidades básicas você poderá explorar os outros (numerosos) módulos que o ajudarão no gerenciamento dos projetos.",
startGuideImputation: "Recursos informam o trabalho realizado diariamente em cada atividade na tela Alocação real de trabalho.<br/> Reestimativa do trabalho « restante » permite a atualização do planejamento do projeto e do progresso real.",
startGuideIntro: "Aqui está um manual rápido para auxiliá-lo nos seus primeiros passos com o ProjeQtOr.<br>Siga estes passos para criar os primeiros elementos.<br>Não exite em pressionar [F1] para acessar o manual de usuário&#44; onde você encontrará mais informações de ajuda.<br>Retorne à página Hoje para acessar novamente esta tela de &#34;manual rápido&#34;.",
startGuideMilestone: "Marcos são as principais datas dos seus projetos.<br/>Eles determinam as principais entregas e eventos do seu projeto&#44; podendo ser datas fixas ou flutuantes.",
startGuidePlanning: "Planejamento fornece uma visão em formato de Gantt.<br/>Para planejar atividades atribuir os recursos às atividades e definir o trabalho a ser realizado&#44; visto que o Planejamento é orientado à trabalho.<br/>Em seguida&#44; você pode definir o relacionamento entre as atividades (predecessores e sucessores) e marcos...<br/>Por último&#44; você pode executar o cálculo de Planejamento que irá considerar as restrições de cada recurso&#44; como disponibilidade.",
startGuideProject: "Projeto é o principal item no sistema ProjeQtOr.<br/>Todo os outros itens são ligados a um projeto.<br/>Os direitos de acesso também são definidos por projeto.",
startGuideResource: "Recursos são as pessoas que irão trabalhar nas atividades.<br/>Se você marcar que um recurso também « é um usuário »&#44; o recurso poderá se conectar no sistema ProjeQtOr.",
startGuideTicket: "Os Chamados permitem você monitorar qualquer evento pontual ligado ao projeto como erros&#44; bugs ou qualquer tipo de solicitação.<br/>Eles podem ser facilmente copiados para atividades quando necessário&#44; sem a necessidade de redigitar todos os dados e mantendo a ligação com a solicitação original.",
startGuideTitle: "Guia Inicial",
startGuideUser: "Usuários são as pessoas que podem conectar ao sistema. <br/>Eles devem ter um perfil associado&#44; que irá determinar os direitos de acesso aos elementos do sistema.",
